#define DLSS5_LAYER_BENCH 1
#include "hip_reference_network.h"
#include <cmath>
namespace hip_reference {struct LayerBenchmark {static bool Check(Network&n,U block,U pattern){U N=32;std::vector<float>v(N*512);for(size_t i=0;i<v.size();i++){unsigned code=(i*37+i/31)%(pattern==2?127:96),e=code>>3,m=code&7;float x=e?std::ldexp(1.f+m/8.f,int(e)-7):m/512.f;v[i]=pattern==0?0.f:((i%3==0)?-x:x);}auto in=n.Upload(v.data(),v.size()*4),a=n.New(v.size()),b=n.New(v.size());auto name=n.Block(block,"ffwd");n.Run("deep","split_ffn_fused",N*512,n.P(in),n.Weight(name),n.P(a),N);n.Run("deep","split_ffn_fused_fp8",N*512,n.P(in),n.PackedSplitFfnWeight(name),n.P(b),N);n.Synchronize();std::vector<float>x(v.size()),y(v.size());n.api.Check(n.api.hipMemcpy(x.data(),n.P(a),x.size()*4,2),"original read");n.api.Check(n.api.hipMemcpy(y.data(),n.P(b),y.size()*4,2),"packed read");size_t diff=0,bad=0;for(size_t i=0;i<x.size();i++){diff+=memcmp(&x[i],&y[i],4)!=0;bad+=!std::isfinite(x[i])||!std::isfinite(y[i]);}printf("block=%u pattern=%u bitdiff=%zu invalid=%zu\n",block,pattern,diff,bad);return !diff&&!bad;}};}
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("ASSETS MODULES required");hip_reference::Options o;o.assets=argv[1];o.modules=argv[2];o.fast_deep=o.packed_weights=true;hip_reference::Network n(o);bool ok=true;for(unsigned b:{23u,24u,25u,26u,27u,28u,29u,30u,40u,41u,42u,43u,44u,45u,46u,47u})for(unsigned p=0;p<3;p++)ok=hip_reference::LayerBenchmark::Check(n,b,p)&&ok;return ok?0:1;}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 2;}}
